    41  Elf_Cmd
    42  elf_next (Elf *elf)
    43  {
    44    Elf *parent;
    45    Elf_Cmd ret;
    46
    47    /* Be gratious, the specs demand it.  */
    48    if (elf == NULL || elf->parent == NULL)
    49      return ELF_C_NULL;
    50
    51    /* We can be sure the parent is an archive.  */
    52    parent = elf->parent;
    53    assert (parent->kind == ELF_K_AR);
    54
    55    rwlock_wrlock (parent->lock);
    56
    57    /* Now advance the offset.  */
    58    parent->state.ar.offset += (sizeof (struct ar_hdr)
    59                                + ((parent->state.ar.elf_ar_hdr.ar_size + 1)
    60                                   & ~1l));
    61
    62    /* Get the next archive header.  */
    63    ret = __libelf_next_arhdr_wrlock (parent) != 0 ? ELF_C_NULL : elf->cmd;
    64
    65    /* If necessary, mark the archive header as unusable.  */
    66    if (ret == ELF_C_NULL)
    67      parent->state.ar.elf_ar_hdr.ar_name = NULL;
    68
    69    rwlock_unlock (parent->lock);
    70
    71    return ret;
    72  }
