    41  Elf_Arhdr *
    42  elf_getarhdr (Elf *elf)
    43  {
    44    if (elf == NULL)
    45      return NULL;
    46
    47    Elf *parent = elf->parent;
    48
    49    /* Calling this function is not ok for any file type but archives.  */
    50    if (parent == NULL)
    51      {
    52        __libelf_seterrno (ELF_E_INVALID_OP);
    53        return NULL;
    54      }
    55
    56    /* Make sure we have read the archive header.  */
    57    if (parent->state.ar.elf_ar_hdr.ar_name == NULL
    58        && __libelf_next_arhdr_wrlock (parent) != 0)
    59      {
    60        rwlock_wrlock (parent->lock);
    61        int st = __libelf_next_arhdr_wrlock (parent);
    62        rwlock_unlock (parent->lock);
    63
    64        if (st != 0)
    65          /* Something went wrong.  Maybe there is no member left.  */
    66          return NULL;
    67      }
    68
    69    /* We can be sure the parent is an archive.  */
    70    assert (parent->kind == ELF_K_AR);
    71
    72    return &parent->state.ar.elf_ar_hdr;
    73  }
